#pragma once
#include "storage/StorageEnvelope.hpp"
#include "platform/ProfileAccessMac.hpp"
#include <cstdint>
#include <vector>
#include <cctype>
namespace fathom::storage::profile_names {
inline constexpr const char* key="profile_identity";
struct Unit{std::uint32_t code;std::string bytes;};
inline bool space(std::uint32_t c){return c==32||(c>=9&&c<=13)||c==0x85||c==0xa0||c==0x1680||(c>=0x2000&&c<=0x200a)||c==0x2028||c==0x2029||c==0x202f||c==0x205f||c==0x3000;}
inline std::vector<Unit> units(const std::string&s){std::vector<Unit> out;for(std::size_t i=0;i<s.size();){const auto start=i;unsigned char a=s[i++];std::uint32_t c=a;unsigned extra=0;if(a<0x80){}else if(a>=0xc2&&a<=0xdf){c=a&31;extra=1;}else if(a>=0xe0&&a<=0xef){c=a&15;extra=2;}else if(a>=0xf0&&a<=0xf4){c=a&7;extra=3;}else throw std::invalid_argument("Use valid Unicode in the profile name.");if(i+extra>s.size())throw std::invalid_argument("Use valid Unicode in the profile name.");for(unsigned j=0;j<extra;++j){unsigned char b=s[i++];if((b&0xc0)!=0x80)throw std::invalid_argument("Use valid Unicode in the profile name.");c=(c<<6)|(b&63);}if((extra==1&&c<0x80)||(extra==2&&c<0x800)||(extra==3&&c<0x10000)||c>0x10ffff||(c>=0xd800&&c<=0xdfff))throw std::invalid_argument("Use valid Unicode in the profile name.");out.push_back({c,s.substr(start,i-start)});}return out;}
inline std::string normalize(const std::string&s){if(s.size()>256)throw std::invalid_argument("Use a profile name of 1–64 characters.");auto v=units(s);std::size_t a=0,b=v.size();while(a<b&&space(v[a].code))++a;while(b>a&&space(v[b-1].code))--b;if(a==b||b-a>64)throw std::invalid_argument("Enter a profile name of 1–64 characters.");std::string result;for(auto i=a;i<b;++i){auto c=v[i].code;if(c<32||(c>=127&&c<=159)||c=='/'||c=='\\'||c==':'||c==0x2028||c==0x2029)throw std::invalid_argument("Profile names cannot contain /, \\, :, or control characters.");result+=v[i].bytes;}if(result=="."||result=="..")throw std::invalid_argument("Choose a descriptive profile name.");return result;}
inline std::string stem(const std::string&name){std::string out;for(const auto&u:units(normalize(name))){std::string part;if(u.code<128&&std::isalnum(static_cast<unsigned char>(u.code)))part=std::string(1,static_cast<char>(std::tolower(static_cast<unsigned char>(u.code))));else if(u.code>=160&&!space(u.code)){part="u";auto c=u.code;std::string hex;do{hex="0123456789abcdef"[c&15]+hex;c>>=4;}while(c);part+=hex;}else part="-";if(out.size()+part.size()>80)break;if(part!="-"||(!out.empty()&&out.back()!='-'))out+=part;}while(!out.empty()&&out.back()=='-')out.pop_back();return out.empty()?"profile":out;}
inline std::string filename(const std::string&name,const std::string&token){validateUuid(token);return stem(name)+"--"+token+".fathom.sqlite";}
inline bool databaseName(const std::string&name){if(name=="profile.sqlite")return true;const std::string suffix=".fathom.sqlite";if(name.size()<=suffix.size()+38||name.compare(name.size()-suffix.size(),suffix.size(),suffix)!=0||name.find('/')!=std::string::npos||name.find('\\')!=std::string::npos||name.find(':')!=std::string::npos||name.front()=='.')return false;const auto pos=name.size()-suffix.size()-36;if(pos<2||name.substr(pos-2,2)!="--")return false;try{validateUuid(name.substr(pos,36));auto prefix=name.substr(0,pos-2);if(prefix.empty()||prefix.size()>80||prefix.front()=='-'||prefix.back()=='-')return false;for(const auto c:prefix)if(!((c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='-'))return false;return true;}catch(...){return false;}}
inline Value identity(const std::string&profile,const std::string&name,const std::string&token){validateUuid(profile);return Value::Object{{"format","Fathom.ProfileIdentity.1"},{"profile_id",profile},{"display_name",normalize(name)},{"file_token",token},{"recovery_file",filename(name,token)}};}
inline bool valid(const Value&v)noexcept{try{const auto&o=v.object();if(o.size()!=5||o.at("format")!=Value("Fathom.ProfileIdentity.1"))return false;validateUuid(o.at("profile_id").string());return normalize(o.at("display_name").string())==o.at("display_name").string()&&o.at("recovery_file")==Value(filename(o.at("display_name").string(),o.at("file_token").string()));}catch(...){return false;}}
inline bool preferenceValidator(const std::string&k,std::int64_t version,const Value&v)noexcept{return k==key&&version==1&&valid(v);}
}
